<?php require "db.php"; require "auth.php"; requireLogin();
$stmt=$pdo->prepare("SELECT b.* FROM books b JOIN library l ON l.book_id=b.id WHERE l.user_id=?"); $stmt->execute([currentUserId()]); $books=$stmt->fetchAll();
